admin_dash:()=>{const st=S.users.filter(u=>u.role==='student'),mt=S.users.filter(u=>u.role==='mentor'),mo=[...Array(12)].map((_,i)=>[st,mt].map(l=>l.filter(u=>new Date(u.created).getMonth()===i&&new Date(u.created).getFullYear()===new Date().getFullYear()).length)),mx=Math.max(1,...mo.flat()),pt=k=>mo.map((v,i)=>`${20+i*50},${130-v[k]/mx*110}`).join(' ');
 return `<div class="grid g4">${stat('Total de estudiantes',st.length)}${stat('Total de mentores',mt.length)}${stat('Mentores activos',mt.filter(u=>u.active!==false).length)}${stat('Solicitudes pendientes',S.reqs.filter(r=>r.status==='PENDIENTE').length)}${stat('Mentorías activas',S.reqs.filter(r=>r.status==='ACEPTADA'&&(r.sesion||'Confirmada')==='Confirmada').length)}${stat('Mensajes / conexiones',S.chats.reduce((a,c)=>a+(c.count||0),0))}</div><div class="grid g2" style="margin-top:16px"><div class=card><h3>Registros por mes (este año)</h3><svg viewBox="0 0 600 150" width=100%><polyline fill=none stroke="#2563eb" stroke-width=3 points="${pt(0)}"/><polyline fill=none stroke="#7c3aed" stroke-width=3 points="${pt(1)}"/></svg><small><span style=color:#2563eb>● Estudiantes</span> <span style=color:#7c3aed>● Mentores</span> · Ene→Dic</small></div><div class=card><h3>Solicitudes recientes</h3>${[...S.reqs].sort((a,b)=>b.created-a.created).slice(0,5).map(r=>`<p>${esc(U(r.student).name)} → ${esc(U(r.mentor).name)} <span class="badge ${stB(r.status)}">${r.status}</span></p>`).join('')||'<p class=sub>Sin solicitudes.</p>'}</div><div class=card><h3>Usuarios recientes</h3>${[...S.users].sort((a,b)=>b.created-a.created).slice(0,5).map(u=>`<p class=row>${av(u,28)}${esc(u.name)} <span class=badge>${u.role}</span></p>`).join('')}</div><div class=card><h3>Últimas actividades</h3>${[...S.notifs].sort((a,b)=>b.ts-a.ts).slice(0,6).map(n=>`<p>${esc(n.text)} <small>${ago(n.ts)}</small></p>`).join('')||'<p class=sub>Sin actividad.</p>'}</div></div>`},
