admin_mentorias:()=>`<div style="margin-bottom:12px"><button class="btn p" data-a=mnew>+ Programar mentoría</button></div><div class="card tw"><table><tr><th></th><th>Mentor</th><th>Estudiante</th><th>Especialidad</th><th>Fecha</th><th>Hora</th><th>Estado</th></tr>${S.reqs.filter(r=>r.status==='ACEPTADA').map(r=>`<tr><td><button class="btn d" data-a=rdel data-id=${r.id}>Eliminar</button></td><td>${esc(U(r.mentor).name)}</td><td>${esc(U(r.student).name)}</td><td>${esc(r.specialty)}</td><td>${fdate(r.date)}</td><td>${esc(r.time)}</td><td><select data-in=ases data-id=${r.id}>${['Pendiente','Confirmada','Finalizada','Cancelada'].map(s=>`<option ${(r.sesion||'Confirmada')===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')||'<tr><td>Sin mentorías.</td></tr>'}</table></div>`,
